+  if (tx < kRadix + 1) histogram[tx] = 0;
+  if (tx == 0) {
+    counter = 0;
+    threshold_bin_id = -1;
+    num_input[0] = 0;
+    num_input[1] = 0;
+  }
+  __syncthreads();
